-- Growths — Escola Aurora · PARTE 3 de 4: imagens dos criativos (12 anúncios). Rode depois da parte 1. Pode rodar de novo.
update anuncios a set imagem_url = x.img from (values
('AD02 · Entende mas não fala · Reels','data:image/webp;base64,'),
('AD05 · Semana da Fluência · aulas grátis · Estático','data:image/webp;base64,'),
('AD08 · Antes e depois · áudio real · Reels','data:image/webp;base64,'),
('AD11 · Depoimento Carla · 6 meses · Reels','data:image/webp;base64,'),
('AD14 · Aula ao vivo 27/10 · Stories','data:image/webp;base64,'),
('AD17 · Depoimento Carla · 6 meses · Reels','data:image/webp;base64,'),
('AD20 · Faltam poucos dias · Stories','data:image/webp;base64,'),
('AD23 · Bastidores da aula · Reels','data:image/webp;base64,'),
('AD26 · Bumper 6s · Semana da Fluência · Vídeo','data:image/webp;base64,'),
('AD29 · POV: você trava no inglês · Vertical','data:image/webp;base64,'),
('Perpétuo · Dor da trava','data:image/webp;base64,'),
('Pesquisa · curso de inglês','data:image/webp;base64,')
) x(nome, img), workspaces w
where w.nome = 'Escola Aurora' and a.workspace_id = w.id and a.nome = x.nome;
select count(*) filter (where a.imagem_url is not null) as anuncios_com_imagem, count(*) as anuncios from anuncios a join workspaces w on w.id = a.workspace_id where w.nome = 'Escola Aurora';
